// App icon links, shared by the React document head (__root.tsx) and the raw HTML error page
// the server returns (error-page.ts), so every page shows the same SCDMS icon.
// Bump ICON_VERSION whenever the files in public/ change, so browsers drop cached icons.
// The icon files are generated by scripts/generate-icons.mjs.
export const ICON_VERSION = "2";

export const ICON_LINKS: { rel: string; href: string; type?: string; sizes?: string }[] = [
  { rel: "icon", href: `/favicon.svg?v=${ICON_VERSION}`, type: "image/svg+xml" },
  { rel: "icon", href: `/favicon.ico?v=${ICON_VERSION}`, sizes: "48x48" },
  { rel: "apple-touch-icon", href: `/apple-touch-icon.png?v=${ICON_VERSION}`, sizes: "180x180" },
  { rel: "manifest", href: `/site.webmanifest?v=${ICON_VERSION}` },
];

export const THEME_COLOR = "#4f46e5";

/** The icon links as an HTML string, for pages rendered outside React. */
export function iconLinksHtml(): string {
  return ICON_LINKS.map(
    (l) =>
      `<link rel="${l.rel}" href="${l.href}"${l.type ? ` type="${l.type}"` : ""}${l.sizes ? ` sizes="${l.sizes}"` : ""} />`,
  ).join("\n    ");
}
